window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"GNALugvzquc","speaker":"Karol Nawrocki","role":"President","country":"Poland","region":"Europe","url":"https://www.youtube.com/watch?v=GNALugvzquc","date":"20260923","title":"🇵🇱 Poland - President Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1543,"words":3398,"counts":{"claims":43,"promises":1,"attacks":3},"topics":[{"topic":"Russia aggression","share":0.1805,"seconds":279},{"topic":"UN reform","share":0.171,"seconds":264},{"topic":"AI regulation","share":0.0874,"seconds":135},{"topic":"Environmental policy","share":0.0797,"seconds":123},{"topic":"Poland economy","share":0.0513,"seconds":79},{"topic":"G20 expansion","share":0.0446,"seconds":69},{"topic":"Poland solidarity","share":0.0443,"seconds":68},{"topic":"Christian persecution","share":0.0416,"seconds":64},{"topic":"Polish aid","share":0.0411,"seconds":63},{"topic":"G20 summit","share":0.0409,"seconds":63},{"topic":"Demographic crisis","share":0.0408,"seconds":63},{"topic":"Central Europe economy","share":0.0407,"seconds":63},{"topic":"Energy sovereignty","share":0.0396,"seconds":61},{"topic":"Israel-Gaza","share":0.0394,"seconds":61},{"topic":"Accountability principle","share":0.0392,"seconds":60},{"topic":"Poland stance","share":0.0178,"seconds":27}],"timeline":[[2,69,null],[70,144,"UN reform"],[145,208,"UN reform"],[208,269,"Accountability principle"],[269,345,"Russia aggression"],[345,406,"Russia aggression"],[407,477,"Russia aggression"],[480,552,"Russia aggression"],[553,616,"UN reform"],[617,677,"Israel-Gaza"],[678,758,"Poland economy"],[759,828,"G20 expansion"],[828,891,"Central Europe economy"],[892,953,"Energy sovereignty"],[954,1017,"G20 summit"],[1018,1081,"Demographic crisis"],[1083,1146,"Polish aid"],[1147,1209,"Environmental policy"],[1210,1272,"Environmental policy"],[1273,1341,"Poland solidarity"],[1342,1406,"Christian persecution"],[1407,1481,"AI regulation"],[1482,1543,"AI regulation"],[1544,1608,"UN reform"],[1610,1637,"Poland stance"]],"stances":{"UN reform":"Karol Nawrocki argues that the UN was established with a fundamental flaw because it failed to ensure accountability for wrongdoing, citing Poland's historical experience under totalitarian regimes as evidence.","Accountability principle":"Karol Nawrocki argues that restoring the full meaning of the accountability principle is essential for lasting peace and effective international law.","Russia aggression":"Karol Nawrocki asserts that Russia's actions constitute a violation of UN principles and international law, describing them as destabilizing and imperialistic.","Israel-Gaza":"Karol Nawrocki states that Poland supports de-escalation, civilian protection, and the implementation of a two-state solution for Israel.","Poland economy":"Karol Nawrocki states that Poland's economic success is the result of consistent reforms and societal effort rather than chance, and advocates for international cooperation based on mutual respect and sovereignty.","G20 expansion":"Karol Nawrocki supports the inclusion of the African Union in the G20 and advocates for the inclusion of Central Europe to ensure more representative governance.","Central Europe economy":"Karol Nawrocki describes Central Europe as a region of dynamic growth and innovation that serves as a voice for its unique perspective, emphasizing cooperation in infrastructure, energy, and security to build economic resilience.","Energy sovereignty":"Karol Nawrocki states that energy sovereignty, including nuclear energy, is a prerequisite for security and political independence rather than a choice.","G20 summit":"Karol Nawrocki expresses gratitude for the US invitation to the G20 and highlights the demographic crisis as a civilizational challenge requiring institutional and cultural responses.","Demographic crisis":"Karol Nawrocki argues that protecting the family is essential to overcoming demographic crises and that illegal migration cannot serve as a solution because it causes misery and unrest.","Polish aid":"Karol Nawrocki states that Poland consistently supports international efforts to resolve the Middle East crisis and is committed to providing humanitarian aid and development initiatives in Palestine and Lebanon.","Environmental policy":"Karol Nawrocki argues that environmental policies must not weaken economies or shift problems to other countries, warning that ambitious measures without global coordination lead to de-industrialization and emission exports rather than genuine climate protection.","Poland solidarity":"Karol Nawrocki asserts that human rights are foundational to international politics and cites the Polish Solidarity movement as a historical example of people refusing to live under a system based on lies and violence.","Christian persecution":"Karol Nawrocki states that Christian communities face persecution, discrimination, and violence in conflict regions, leading to a dramatic decline in their numbers and the loss of their historical heritage.","AI regulation":"Karol Nawrocki argues that new technologies like artificial intelligence must serve humanity and not exploit people, while warning of the risks of humans becoming objects of algorithmic influence.","Poland stance":"Karol Nawrocki states that Poland will always support the law, responsibility, humanity, and freedom."},"claims":[{"t":70,"quote":"Poland was in fact a founding member of the United Nations.","topic":"UN reform","kind":"fact"},{"t":99,"quote":"The UN was established in response to the greatest tragedy in human history, World War II.","topic":"UN reform","kind":"fact"},{"t":124,"quote":"My nation, a victim of two totalitarian regimes, was under the domination of one of them, Soviet Russia.","topic":"UN reform","kind":"fact"},{"t":145,"quote":"The UN already existed at that time. At the same time, the state responsible for those crimes had a say in shaping the post-war order as a permanent member of the security council.","topic":"UN reform","kind":"fact"},{"t":159,"quote":"Poland has never received redress for that period and those wrongs.","topic":"UN reform","kind":"fact"},{"t":208,"quote":"A state that has not been held accountable for its actions is more likely to resort to the same tools again.","topic":"Accountability principle","kind":"fact"},{"t":224,"quote":"Without it, there will not be a lasting peace and international law will remain nothing more than a declaration devoid of real power.","topic":"Accountability principle","kind":"fact"},{"t":279,"quote":"a permanent member of the council, Russia, attempts unsuccessfully but with ruthless persistence to concare a neighboring state and destabilize the entire region is a violation of the principles we all uphold as signaries to the charter of the United Nations.","topic":"Russia aggression","kind":"fact"},{"t":298,"quote":"Russia is destabilizing the situation in Europe through open aggression, hybrid operations, acts of subversion and sabotage, and by ignoring successive resolutions of this It displays the same imperial arrogance that in the past led to unimaginable suffering and the tragedies of two world wars.","topic":"Russia aggression","kind":"fact"},{"t":346,"quote":"the Russian Federation, guided by an imperial and neocolonial vision of the world, is attempting to impose its will on others.","topic":"Russia aggression","kind":"fact"},{"t":361,"quote":"Neoimperial and neoc colonial policies are in essence an attempt to return to a world in which the borders, security and future of states and nations would be decided not by the states and nations themselves but by other states that consider themselves stronger and predestined to dominate and there might would replace law.","topic":"Russia aggression","kind":"fact"},{"t":425,"quote":"We are strengthening our alliances, developing our military, and modernizing its equipment, not to wage war, but to prevent it.","topic":"Russia aggression","kind":"fact"},{"t":452,"quote":"NATO remains united in the overarching goal of defending our community on both sides of the Atlantic in Europe and America on its eastern flank and along its northern border.","topic":"Russia aggression","kind":"fact"},{"t":489,"quote":"Russia is carrying out actions aimed at undermining the foundations of international stability, striking at global food security through attacks on ports and ships transporting grain as well as by deliberately provoking crisis that affect millions of people outside of Europe.","topic":"Russia aggression","kind":"fact"},{"t":509,"quote":"At the same time, a largecale hybrid war is being waged involving sabotage, cyber attacks, and destabilization operations on an unprecedented scale, including an artificially induced migration crisis.","topic":"Russia aggression","kind":"fact"},{"t":584,"quote":"The role of UN peacekeeping operations in preventing the resurgence of conflict is Poland advocates for stable funding of peacekeeping missions and for granting them more transparent mandates that also take into account tasks related to the protection of the population and support for the reconstruction of state institutions. Poland also fulfills its commitments to global security through its participation in UN peacekeeping operations as well.","topic":"UN reform","kind":"fact"},{"t":617,"quote":"Polish blue helmet soldiers are currently serving in Lebanon, carrying out their duties with dignity despite the difficult security situation throughout the region.","topic":"Israel-Gaza","kind":"fact"},{"t":663,"quote":"Poland has no colonial past. Our historical experience is different, marked by the struggle for our own freedom and resistance to domination imposed by force.","topic":"Israel-Gaza","kind":"fact"},{"t":740,"quote":"today Poland is the world's 20th largest","topic":"Poland economy","kind":"number"},{"t":745,"quote":"Our path to becoming a developed nation was not a matter of chance, but the result of consistent reforms, including the fight against corruption, responsible policies, and the efforts of the entire society.","topic":"Poland economy","kind":"fact"},{"t":801,"quote":"In 2023, the African Union was admitted to the This was a good decision.","topic":"G20 expansion","kind":"fact"},{"t":846,"quote":"Central Europe, a co-founder of the 3C's initiative, is not merely a region catching up with the more developed parts of the continent.","topic":"Central Europe economy","kind":"fact"},{"t":864,"quote":"It is one of the most promising areas for economic development in the world.","topic":"Central Europe economy","kind":"fact"},{"t":904,"quote":"The experiences of recent years have clearly shown that countries capable of making themselves independent from energy pressure are also more resilient to blackmail","topic":"Energy sovereignty","kind":"fact"},{"t":954,"quote":"This year we are participating in the group's works at the invitation of the current presidency, the United States.","topic":"G20 summit","kind":"fact"},{"t":970,"quote":"We are actively participating in preparations for this event which will take place in Miami this December.","topic":"G20 summit","kind":"fact"},{"t":1035,"quote":"Without enduring communities and strong families, there will neither be stable development nor long-term security.","topic":"Demographic crisis","kind":"fact"},{"t":1066,"quote":"illegal migration which often takes the form of human trafficking","topic":"Demographic crisis","kind":"fact"},{"t":1090,"quote":"for years we have consistently supported international efforts to resolve the crisis in the Middle East","topic":"Polish aid","kind":"fact"},{"t":1115,"quote":"In Palestine, we continue to support the operation of mobile clinics, providing medical care in the West Bank","topic":"Polish aid","kind":"fact"},{"t":1176,"quote":"Pushing for ambitious environmental policies without considering their global consequences may result in de-industrialization, longer supply chains, and the relocation of production to countries that do not apply comparable standards.","topic":"Environmental policy","kind":"fact"},{"t":1194,"quote":"This path does not lead to genuine climate protection. It merely leads to the export of emissions to other parts of the same globe accompanied by job losses in the country of origin and the erosion of production capacity.","topic":"Environmental policy","kind":"fact"},{"t":1226,"quote":"nature not as a resource to be exploited but as a gift entrusted to humankind our common home for which we are responsible as its guardians","topic":"Environmental policy","kind":"fact"},{"t":1250,"quote":"careful nature is much older than the left-wing concepts it stems from an ethic that took shape long before the emergence of ideals","topic":"Environmental policy","kind":"fact"},{"t":1297,"quote":"The social movement that led to the fall of the communist government imposed on Poland was called solidarity.","topic":"Poland solidarity","kind":"fact"},{"t":1304,"quote":"It was an expression of the courage of people who despite repression and the lack of freedom refused to live under a system based on lies and violence.","topic":"Poland solidarity","kind":"fact"},{"t":1366,"quote":"Until recently, Christian communities were a natural part of social life prisoned for 2,000 years, helping to shape the culture, language, and identity of entire regions.","topic":"Christian persecution","kind":"fact"},{"t":1379,"quote":"Today, in many places, their numbers have dwindled dramatically. Sometimes, only traces of their former presence remain.","topic":"Christian persecution","kind":"fact"},{"t":1465,"quote":"As early as in the 1980s, an eminent Polish writer Staniswat LM in his novel Fiasco warned that the moment we teach machines to think, we will face questions not only about their capabilities but also about their ambitions.","topic":"AI regulation","kind":"fact"},{"t":1493,"quote":"It is precisely the development of technology that is playing a decisive role in co-shaping the realities of the 21st century.","topic":"AI regulation","kind":"fact"},{"t":1552,"quote":"The world is changing. The UN must change as well.","topic":"UN reform","kind":"fact"},{"t":1577,"quote":"the development of artificial intelligence, which is outpacing existing rules and testing the limits of our","topic":"UN reform","kind":"fact"},{"t":1610,"quote":"Poland and I want to convince you about that ladies and gentlemen will always stand on the side of the law responsibility humanity and freedom.","topic":"Poland stance","kind":"fact"}],"promises":[{"t":628,"quote":"We will support efforts to deescalate conflicts, protect civilians, and uphold international humanitarian law, and work toward the implementation of a two-state solution, ensuring the peaceful coexistence of Israel and","topic":"Israel-Gaza","kind":"promise"}],"attacks":[{"t":312,"quote":"It displays the same imperial arrogance that in the past led to unimaginable suffering and the tragedies of two world wars.","topic":"Russia aggression","target":"Russia"},{"t":346,"quote":"the Russian Federation, guided by an imperial and neocolonial vision of the world, is attempting to impose its will on others.","topic":"Russia aggression","target":"Russia"},{"t":489,"quote":"Russia is carrying out actions aimed at undermining the foundations of international stability, striking at global food security through attacks on ports and ships transporting grain as well as by deliberately provoking crisis that affect millions of people outside of Europe.","topic":"Russia aggression","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"And now uh the eighth plenary meeting of the general assembly is called to order and the assembly will hear the address of his excellency Carl Navroski, President of the Republic of Poland. I request the protocol uh to escort his excellency and invite him to address the assembly. Distinguished Mr. President, I'm absolutely delighted that we are here today. Thank you so much for your hard work for the United Nations Organization and for the Republic of Poland. Distinguished excellencies, distinguished guests, the 81st session of the UN General Assembly begins at one of the most difficult in my view moments since the organization's founding."},{"t":70,"topic":"UN reform","text":"Poland was in fact a founding member of the United Nations. From the very beginning of the UN's existence, we have been faced with a question about the foundations of the international order that we are shaping within our organization. Despite many achievements, we must not forget that at the very root of its creation lies a fundamental flaw, an original flaw that continues to undermine the systems credibility to this day. The UN was established in response to the greatest tragedy in human history, World War II. that it was not funded on a simple and fundamental principle that every wrongdoing must be met with accountability and sometimes with just punishment. For Poland, this is not an abstract issue. At the very moment, the foundations of the UN were being laid. My nation, a victim of two totalitarian regimes, was under the domination of one of them, Soviet Russia. And after several years of devastating occupation of the other, thousands of Polish heroes who fought for the freedom of Europe and the entire world were at that time imprisoned, tortured, and sentenced to death."},{"t":145,"topic":"UN reform","text":"The UN already existed at that time. At the same time, the state responsible for those crimes had a say in shaping the post-war order as a permanent member of the security council. Poland has never received redress for that period and those wrongs. The failure to hold anyone accountable for these crimes was not merely historical oversight. It sent a signal that violations of international law aggression and imperialist policies could go unpunished in reality. It is precisely this lack of justice, this sort of original scene of the post-war order that creates space for the return of old aggressive ambitions and methods of operation. The aggressive policies of certain states today is therefore not a phenomenon detached from history. These policies are direct consequence of it."},{"t":208,"topic":"Accountability principle","text":"A state that has not been held accountable for its actions is more likely to resort to the same tools again. That is why it is so important that today as the international community would restore the full meaning of the principle of accountability. Without it, there will not be a lasting peace and international law will remain nothing more than a declaration devoid of real power. Ladies and gentlemen, today we must show courage while remembering that sometimes courage alone is not enough. That without prudence, courage can lead to disaster. True leadership requires both. Prudence in this case means not only knowing what we want. It also is about um pursue of goal while calling aggression by its name and also condemning those who disrupt the world order without turning a blind eye when they violate the rules."},{"t":269,"topic":"Russia aggression","text":"Ladies and gentlemen, for many years, representatives of my country have been trying in this chamber and in the security council to point out that a situation in which a permanent member of the council, Russia, attempts unsuccessfully but with ruthless persistence to concare a neighboring state and destabilize the entire region is a violation of the principles we all uphold as signaries to the charter of the United Nations. Russia is destabilizing the situation in Europe through open aggression, hybrid operations, acts of subversion and sabotage, and by ignoring successive resolutions of this It displays the same imperial arrogance that in the past led to unimaginable suffering and the tragedies of two world wars. Contempt for international law must not become the norm. It is not too late to restore the primacy of international law and strengthen the foundations of a system in which principles matter and in which the international community acting jointly and in solidarity opposes aggression which is prohibited by the chart of the United Nations."},{"t":345,"topic":"Russia aggression","text":"Ladies and gentlemen, the Russian Federation, guided by an imperial and neocolonial vision of the world, is attempting to impose its will on others. In doing so, it is effectively challenging the right of every nation and to determine its own destiny. Neoimperial and neoc colonial policies are in essence an attempt to return to a world in which the borders, security and future of states and nations would be decided not by the states and nations themselves but by other states that consider themselves stronger and predestined to dominate and there might would replace law. It is an attempt to return to the concert of powers. This cannot be accepted. It is the force of law that should decide, not the law force. Poland is particularly aware of the consequences of Russian colonialism and History has taught us that freedom and sovereignty cannot defend themselves."},{"t":407,"topic":"Russia aggression","text":"That is why we are determined to counter the threats that the Kremlin's aggressive policies are posing to us with increasing audacity. As a representative of a country neighboring Russia, I want to make it clear. We are not the ones seeking confrontation. We are strengthening our alliances, developing our military, and modernizing its equipment, not to wage war, but to prevent it. Our goal is deterrence and defense. The defense of two values that also form the foundation of the United Nations Charter, freedom and We continue to view the North Atlantic Alliance as the guarantor of European security. NATO remains united in the overarching goal of defending our community on both sides of the Atlantic in Europe and America on its eastern flank and along its northern border. We therefore welcome with satisfaction the strengthening of security in the Arctic region which is now becoming a reality thanks to the agreement signed yesterday between our allies."},{"t":480,"topic":"Russia aggression","text":"Ladies and gentlemen, we must however make it clear modern security threats are not limited to classical military actions. Russia is carrying out actions aimed at undermining the foundations of international stability, striking at global food security through attacks on ports and ships transporting grain as well as by deliberately provoking crisis that affect millions of people outside of Europe. At the same time, a largecale hybrid war is being waged involving sabotage, cyber attacks, and destabilization operations on an unprecedented scale, including an artificially induced migration crisis. These are planned, coordinated, and consistently executed actions. Their goal is to weaken states, undermine public trust, and shatter the unity of the international community. We are not dealing with isolated incidents, but with a sustained well-thoughtout strategy, and that is precisely why the response to these actions cannot be ad hoc or half-hearted."},{"t":553,"topic":"UN reform","text":"It must be firm, consistent, and it must also be united. For if aggression, whether military or hybrid in nature, is not met with an adequate response, it becomes an invitation to repeat it. Ladies and gentlemen, even if today we have reservations about the effectiveness of the security council, we respect the achievements of the United Nations in maintaining and building peace in many parts of the world. The role of UN peacekeeping operations in preventing the resurgence of conflict is Poland advocates for stable funding of peacekeeping missions and for granting them more transparent mandates that also take into account tasks related to the protection of the population and support for the reconstruction of state institutions. Poland also fulfills its commitments to global security through its participation in UN peacekeeping operations as well."},{"t":617,"topic":"Israel-Gaza","text":"Polish blue helmet soldiers are currently serving in Lebanon, carrying out their duties with dignity despite the difficult security situation throughout the region. We will support efforts to deescalate conflicts, protect civilians, and uphold international humanitarian law, and work toward the implementation of a two-state solution, ensuring the peaceful coexistence of Israel and Ladies and gentlemen, this is precisely why the response to contemporary threats cannot be limited solely to reacting to crisis. It must be based on clear principles and reliable partnerships. Poland has no colonial past. Our historical experience is different, marked by the struggle for our own freedom and resistance to domination imposed by force."},{"t":678,"topic":"Poland economy","text":"In international relations, we advocate an approach based on mutual respect, sovereignty, and the equality of states. Poland does not seek an advantage over others. On the contrary, it builds cooperation that strengthens all participants in a world of growing geopolitical rivalry. We need more partnerships that create real value rather than deepening dependencies. That is why Poland consistently works toward a model of international cooperation that gives countries room to develop, strengthens their resilience, and allows them to make sovereign decisions. This approach is reflected both in our own regional policy and in our global We propose partnership instead of It is in this spirit that we view our role in the global economy and our engagement in international initiatives. Ladies and gentlemen, today Poland is the world's 20th largest Our path to becoming a developed nation was not a matter of chance, but the result of consistent reforms, including the fight against corruption, responsible policies, and the efforts of the entire society."},{"t":759,"topic":"G20 expansion","text":"We view this experience not as a reason for complacency but as a commitment to share with others. As we engage in the work of the G20, we view this forum as key to rebuilding trust in international relations and developing responses to the most important challenges of the modern world. from economic security through supply chain resilience to the stability of the trading system. In this context, an important step toward a more representative governance structure was the decision to expand this format so that every region could be represented. In 2023, the African Union was admitted to the This was a good decision. It has strengthened the voice of the African continent and it better reflects the actual processes taking place in the global economy. Now it is the time for the voice of central Europe which has been absent from this forum until now to be heard in the G20 as well."},{"t":828,"topic":"Central Europe economy","text":"This is a region that is developing dynamically and has a slightly different perspective and set of experiences compared to its western partners and friends. Poland will be the voice of this region as a country that understands both the challenges of development and the importance of stable rules of the game in the international economy. Central Europe, a co-founder of the 3C's initiative, is not merely a region catching up with the more developed parts of the continent. It is a region of dynamic growth, rising innovation and exceptional drive. It is one of the most promising areas for economic development in the world. The foundation of this dynamism is cooperation including in the areas of infrastructure and energy, strengthening transportation links, developing north south corridors and investing in security and diversification of energy sources. All of this is translating directly to building the resilience of our economies."},{"t":892,"topic":"Energy sovereignty","text":"Energy sovereignty, including the one based on nuclear energy, is not a choice today. It is a prerequisite for security and political independence. The experiences of recent years have clearly shown that countries capable of making themselves independent from energy pressure are also more resilient to blackmail and That is why we view the development of regional cooperation as an essential contribution to building a more stable and predictable global economic order. We believe that we must respond jointly to the challenges of the 21st century. For us, natural partners in this effort also include countries in Africa, Asia, and Latin America with whom we share the experience of development, the ambition to modernize, and the drive to strengthen sovereignty. I believe that everyone will benefit from Poland's membership in the G20."},{"t":954,"topic":"G20 summit","text":"This year we are participating in the group's works at the invitation of the current presidency, the United States. I would like to thank President Donald Trump very much for inviting us to the G20 summit. We are actively participating in preparations for this event which will take place in Miami this December. At the same time, we must be aware that sustainable economic development and international stability are not possible without addressing the structural challenges that affect many regions of the world today. One of these is the demographic crisis. This is not merely a matter of statistics but a challenge to civilization itself. Aging societies, falling birth rates, and the erosion of social bonds are undermining the foundations of our nations. The response cannot consist solely of economic measures. We also need to rebuild our institutions and culture."},{"t":1018,"topic":"Demographic crisis","text":"We need to protect and value the family and strengthen the social significance of Yes, the family, mother and father, and an appreciation for their roles are the first steps toward overcoming their demographic crisis. Without enduring communities and strong families, there will neither be stable development nor long-term security. Let us do everything we can to ensure that culture and the mass media promote having children, not aborting them. I believe that the UN can be an organization where we can work together to develop ways to gradually overcome the demographic crisis as well as other related challenges such as illegal migration which often takes the form of human trafficking. However, uh an answer to demographic challenges cannot be illegal migration in itself for it breeds misery, tensions and unrest."},{"t":1083,"topic":"Polish aid","text":"This is not the way forward. Ladies and gentlemen, Polish aid embodies global solidarity with those in need. That is why for years we have consistently supported international efforts to resolve the crisis in the Middle East. We are committed to providing humanitarian aid in this region and to development initiatives for Palestine and Lebanon, which are priority countries for Polish aid. We focus on areas critical to sustainable development. Uh in Palestine, we continue to support the operation of mobile clinics, providing medical care in the West Bank, and strengthening employment and professional skills, particularly among women. In Lebanon, Poland is developing the operational capabilities of the Lebanese civil defense units in the area of disaster and natural disaster Ladies and gentlemen, strengthening the resilience of nations and building however, cannot overlook one more dimension of responsibility. The responsibility for the world we will leave to future generations."},{"t":1147,"topic":"Environmental policy","text":"It is our duty to future generations to leave them a clean, safe environment. Poland supports environmental protection efforts, recognizing their impact on security, including food security. Caring for the natural environment is undoubtedly our duty. But fulfilling this duty must not lead to the weakening of our economies or that shifting of problems beyond our borders. Pushing for ambitious environmental policies without considering their global consequences may result in de-industrialization, longer supply chains, and the relocation of production to countries that do not apply comparable standards. This path does not lead to genuine climate protection. It merely leads to the export of emissions to other parts of the same globe accompanied by job losses in the country of origin and the erosion of production capacity."},{"t":1210,"topic":"Environmental policy","text":"We need solutions that combine environmental responsibility with economic competitiveness and economic security. In this spirit, it is worth recalling the message of St. Francis of Aisi who saw nature not as a resource to be exploited but as a gift entrusted to humankind our common home for which we are responsible as its guardians and to put it short ladies and gentlemen we cannot give away the protection of our environment to fanatics careful nature is much older than the left-wing concepts it stems from an ethic that took shape long before the emergence of ideals for concern for creation and concern for humanity are inextricably linked. That is why in the center of our reflection about the future of the world."},{"t":1273,"topic":"Poland solidarity","text":"What must remain is human and their dignity. Ladies and gentlemen, human rights are not an afterthought to international politics. They are at its foundation and also stem from ethical principles older than our organization. Violating them always leads to violence, destabilization and conflict. History, including the history of my country, teaches us this lesson in a very clear way. The social movement that led to the fall of the communist government imposed on Poland was called solidarity. It was an expression of the courage of people who despite repression and the lack of freedom refused to live under a system based on lies and violence. We may differ in our assessments of the extent to which the crimes of the communist system have been addressed. This debate is still ongoing in my country. But this is precisely why we should pay tribute to all those people, especially the workers, thanks to whom we have a free world today and who do not boast of their wealth and status gained the expanse of others, but remain faithful to their values and commitments."},{"t":1342,"topic":"Christian persecution","text":"They are the ones who showed that freedom begins with courage always. Ladies and gentlemen, too many people around the world still face persecution because of their faith. This applies to many different religious communities. But today, we must speak in particular about the plight of Christians in regions affected by conflict and persecution. Until recently, Christian communities were a natural part of social life prisoned for 2,000 years, helping to shape the culture, language, and identity of entire regions. Today, in many places, their numbers have dwindled dramatically. Sometimes, only traces of their former presence remain. Along with these people, a living tradition is disappearing. The heritage of the first centuries of Christianity. This uh legacy has been stopped in many places and perhaps even lost. uh attacks on places of worship, discrimination, violence, and even loss of life."},{"t":1407,"topic":"AI regulation","text":"This is a reality that cannot go unanswered by the international community. Ladies and gentlemen, what threats to human dignity no longer belong exclusively to the physical world. They are increasingly emerging in places where until recently neither the law nor accountability extended. In the digital realm, shaped by the development of new technologies. New technologies such as artificial intelligence or super should always serve humanity as they develop rather than exploit people or their weaknesses. This raises the question of whether in a world of advancing artificial intelligence, humans will remain subjects or become merely objects of algorithmic influence. I'm fully aware that groundbreaking technologies bring not only enormous opportunities but also certain risks. As early as in the 1980s, an eminent Polish writer Staniswat LM in his novel Fiasco warned that the moment we teach machines to think, we will face questions not only about their capabilities but also about their ambitions."},{"t":1482,"topic":"AI regulation","text":"For if they begin to imitate humans in their thinking, a natural consequence may be the drive to surpass them. Today, this challenge takes on a special dimension. It is precisely the development of technology that is playing a decisive role in co-shaping the realities of the 21st century. That is why we need a serious conversation about the limits of artificial intelligence development. We need rules that will actually be enforced and that clearly define where innovation ends and a threat to humanity begins. Artificial intelligence must not be used as a tool for destabilization, manipulation, or undermining the international order. Technology must serve humanity and the truth, not chaos and manipulation. Ladies and gentlemen, uh Poland's priority is order based on truth enshrined in our constitution and resulting from our historical experience."},{"t":1544,"topic":"UN reform","text":"That is why we view the United Nations not merely as a forum for discussion, but as an institution that must be capable of taking action. The world is changing. The UN must change as well. We need an organization that can respond to violations of law, enforce principles, and prevent impunity. UN reform cannot be reduced to mere declarations. It must mean real effectiveness and accountability, including in the face of new challenges such as the demographic crisis or the development of artificial intelligence, which is outpacing existing rules and testing the limits of our We are at a turning point. On the one hand, the logic of force and impunity is making a comeback. On the other, there are technologies that can either reinforce this logic or stop it. It depends on our decisions whether the law will prevail over force and whether humanity will remain more important than the tools it has created."},{"t":1610,"topic":"Poland stance","text":"Poland and I want to convince you about that ladies and gentlemen will always stand on the side of the law responsibility humanity and freedom. Thank you, &gt;&gt; President. On behalf of the assembly, I wish to thank the president of the Republic of Poland. And the assembly will hear now an"}],"compare":[{"topic":"Russia-Ukraine War","share":0.1805,"mean":0.0346,"rank":12,"others":44},{"topic":"UN & its reform","share":0.171,"mean":0.2049,"rank":109,"others":170},{"topic":"Global Economy","share":0.1659,"mean":0.0138,"rank":3,"others":31},{"topic":"Artificial Intelligence","share":0.0874,"mean":0.0503,"rank":43,"others":83},{"topic":"Climate Change","share":0.0797,"mean":0.0426,"rank":44,"others":77},{"topic":"Human Rights","share":0.0416,"mean":0.0084,"rank":21,"others":24},{"topic":"Humanitarian Aid","share":0.0411,"mean":0.0017,"rank":5,"others":5},{"topic":"Europe","share":0.0407,"mean":0.004,"rank":8,"others":8}]};
